from __future__ import annotations

from enum import Enum
from typing import Any

import numpy as np
import torch


class MetricReduction(str, Enum):
    NONE = "none"
    MEAN = "mean"
    SUM = "sum"
    MEAN_BATCH = "mean_batch"
    SUM_BATCH = "sum_batch"
    MEAN_CHANNEL = "mean_channel"
    SUM_CHANNEL = "sum_channel"


def convert_data_type(
    data: Any,
    output_type: type = np.ndarray,
    dtype: Any = None,
    device: Any = None,
    wrap_sequence: bool = False,
):
    if wrap_sequence and isinstance(data, (list, tuple)):
        converted = [
            convert_data_type(item, output_type=output_type, dtype=dtype, device=device)[0]
            for item in data
        ]
        return converted, type(data)
    if output_type is np.ndarray:
        if isinstance(data, torch.Tensor):
            return data.detach().cpu().numpy(), type(data)
        return np.asarray(data, dtype=dtype), type(data)
    return torch.as_tensor(data, dtype=dtype, device=device), type(data)


def convert_to_numpy(data: Any, dtype: Any = None, wrap_sequence: bool = True):
    if isinstance(data, (list, tuple)):
        result = [convert_to_numpy(item, dtype=dtype, wrap_sequence=False) for item in data]
        return result if wrap_sequence else tuple(result)
    if isinstance(data, torch.Tensor):
        return data.detach().cpu().numpy().astype(dtype) if dtype is not None else data.detach().cpu().numpy()
    return np.asarray(data, dtype=dtype)


def convert_to_tensor(data: Any, dtype: Any = None, device: Any = None):
    if isinstance(data, (list, tuple)):
        return [torch.as_tensor(item, dtype=dtype, device=device) for item in data]
    return torch.as_tensor(data, dtype=dtype, device=device)


def ensure_tuple_rep(tup: Any, dim: int):
    if isinstance(tup, (int, float)):
        return (tup,) * dim
    if len(tup) != dim:
        raise ValueError(f"sequence must have length {dim}")
    return tuple(tup)


def look_up_option(opt_str: Any, supported: Any, default: Any = None):
    values = tuple(supported) if not isinstance(supported, dict) else tuple(supported)
    if opt_str in values:
        return opt_str
    if default is not None:
        return default
    raise ValueError(f"Unsupported option: {opt_str}")


def optional_import(module: str, name: str | None = None, version: str | None = None, version_checker: Any = None):
    try:
        imported = __import__(module, fromlist=[name] if name else [])
        value = getattr(imported, name) if name else imported
        return value, True
    except Exception:
        return (None if name else None), False


